GPU_MEM_SIZE = 80 # GB

# EVOLVE-BLOCK-START

def _greedy(gpu_num, sorted_models):
    """Place each model on the GPU with the lowest current KVPR that fits it."""
    placement = {i: [] for i in range(gpu_num)}
    free = [GPU_MEM_SIZE] * gpu_num
    load = [0.0] * gpu_num
    for m in sorted_models:
        best_idx, best_ratio = None, float('inf')
        for g in range(gpu_num):
            if m.model_size <= free[g] and free[g] > 0:
                ratio = load[g] / free[g]
                if ratio < best_ratio:
                    best_ratio, best_idx = ratio, g
        if best_idx is None:
            return None
        placement[best_idx].append(m)
        load[best_idx] += m.req_rate / m.slo
        free[best_idx] -= m.model_size
    return placement


def _max_kvpr(placement):
    """Compute the maximum KVPR over all GPUs in the placement."""
    mx = 0.0
    for mlist in placement.values():
        free = GPU_MEM_SIZE - sum(m.model_size for m in mlist)
        if mlist and free > 0:
            mx = max(mx, sum(m.req_rate / m.slo for m in mlist) / free)
    return mx


def _kvpr(mlist):
    """KVPR of a single GPU's model list."""
    free = GPU_MEM_SIZE - sum(m.model_size for m in mlist)
    if not mlist or free <= 0:
        return 0.0
    return sum(m.req_rate / m.slo for m in mlist) / free


def _refine(p):
    """Hill-climb: move or swap a model off the worst-KVPR GPU when it lowers max KVPR."""
    for _ in range(len(p) * 4):
        k = {g: _kvpr(p[g]) for g in p}
        src = max(p, key=lambda g: k[g])
        cur = max(k.values())
        if k[src] <= 0:
            break
        improved = False
        for m in list(p[src]):
            for dst in p:
                if dst == src:
                    continue
                dst_free = GPU_MEM_SIZE - sum(x.model_size for x in p[dst])
                # try moving m to dst
                if m.model_size <= dst_free:
                    p[src].remove(m); p[dst].append(m)
                    if max(_kvpr(p[g]) for g in p) < cur - 1e-12:
                        improved = True; break
                    p[dst].remove(m); p[src].append(m)
                # try swapping m with a model on dst
                for m2 in list(p[dst]):
                    delta = m2.model_size - m.model_size
                    src_free = GPU_MEM_SIZE - sum(x.model_size for x in p[src])
                    if delta > src_free or -delta > dst_free:
                        continue
                    p[src].remove(m); p[dst].remove(m2)
                    p[src].append(m2); p[dst].append(m)
                    if max(_kvpr(p[g]) for g in p) < cur - 1e-12:
                        improved = True; break
                    p[dst].remove(m); p[src].remove(m2)
                    p[src].append(m); p[dst].append(m2)
                if improved:
                    break
            if improved:
                break
        if not improved:
            break
    return p


def compute_model_placement(gpu_num, models):
    """
    Greedy KVPR-minimizing placement: each model goes to the GPU whose
    current KVPR (load/free) is lowest among GPUs that fit it. Multiple
    model orderings (pressure desc, size desc, pressure/size desc) are
    tried, each refined by a local search (moves/swaps off the worst
    GPU), and the placement with the lowest max KVPR is returned.
    """
    orders = [
        sorted(models, key=lambda m: m.req_rate / m.slo, reverse=True),
        sorted(models, key=lambda m: m.model_size, reverse=True),
        sorted(models, key=lambda m: (m.req_rate / m.slo) / m.model_size, reverse=True),
    ]
    best, best_max = None, float('inf')
    for ms in orders:
        p = _greedy(gpu_num, ms)
        if p is not None:
            p = _refine(p)
            mx = _max_kvpr(p)
            if mx < best_max:
                best, best_max = p, mx
    if best is None:
        raise ValueError("Unable to place all models within GPU memory")
    return best

